        if(turn===1) fullmove++;
        last=[m.from,m.to]; selected=-1; pending=null; promoPanel.textContent='';
        turn=1-turn;
        const moves=allMoves(b,turn,ep,rights), check=inCheck(b,turn);
        const san=notation+(check?(moves.length?'+':'#'):'');
